1	#!/usr/bin/env node
2	/**
3	 * Validate the structure of every result against the contract: the reference
4	 * in `apps/` and each `showcase/<id>/` alike, with no per-result entry.
5	 *
6	 * `validateStructure` is pure. `RULES` holds one entry per rule: how to find
7	 * its violations and how to describe one. The CLI (`node
8	 * tooling/architecture/structure.mjs`, part of `pnpm arch:gate`) reads the
9	 * repository through Fallow and git, prints `OK` with the number of results,
10	 * or prints each violation and exits 1. `--root <dir>` targets another
11	 * repository.
12	 */
13	
14	import { existsSync, readFileSync } from 'node:fs';
15	import { join } from 'node:path';
16	import { pathToFileURL } from 'node:url';
17	import { readRepository, runCli } from './graph.mjs';
18	
19	/** What a result root and each package may hold. Anything else is an unexpected file. */
20	const LAYOUT = {
21	  root: { label: 'a result root', files: ['architecture.mmd'], folders: ['web', 'api'] },
22	  web: {
23	    label: 'a web package',
24	    files: ['package.json', 'index.html', 'vite.config.ts'],
25	    folders: ['src', 'public', 'e2e', 'etc'],
26	  },
27	  api: { label: 'an api package', files: ['package.json'], folders: ['src', 'etc'] },
28	};
29	
30	const DEPENDENCY_FIELDS = [
31	  'dependencies',
32	  'devDependencies',
33	  'peerDependencies',
34	  'optionalDependencies',
35	];
36	
37	/**
38	 * A directive that silences or reconfigures a check: lint and type
39	 * suppressions, ESLint inline config and globals, and coverage pragmas.
40	 */
41	const SUPPRESSION =
42	  /(?:eslint-disable|@ts-(?:expect-error|ignore|nocheck)|biome-ignore|fallow-ignore|\/\*\s*eslint(?:-env)?\s|\/\*\s*globals?\s|(?:istanbul|c8|v8)\s+ignore)/;
43	
44	/** Tool config a result could use to loosen a root gate; allowed only where `LAYOUT` names it. */
45	const CONFIG_FILE =
46	  /^(?:package\.json|[jt]sconfig.*\.json|biome\.jsonc?|eslint\.config\.[cm]?[jt]s|\.eslintrc.*|\.eslintignore|\.npmrc|\.nvmrc|\.gitignore|\.babelrc.*|\.swcrc|\.prettierrc.*|\.fallowrc.*|fallow\.toml|\.size-limit.*|lighthouserc.*|\.browserslistrc|(?:vite|vitest|jest|playwright|babel|postcss|tailwind|webpack|rollup|prettier|commitlint)\.config\.[cm]?[jt]s)$/;
47	
48	/** A file that can hold a role: source and style, not a test, a declaration or a note. */
49	const isRoleSource = (file) =>
50	  /\.(?:tsx?|css)$/.test(file) && !/\.(?:test\.tsx?|d\.ts)$/.test(file);
51	
52	const PACKAGE_KINDS = ['web', 'api'];
53	
54	const sameList = (left, right) => left.join('\n') === right.join('\n');
55	
56	/** JSON text with object keys sorted, so two values compare by content. */
57	const canonical = (value) =>
58	  JSON.stringify(value, (_, inner) =>
59	    inner && typeof inner === 'object' && !Array.isArray(inner)
60	      ? Object.fromEntries(Object.entries(inner).sort(([left], [right]) => (left < right ? -1 : 1)))
61	      : inner,
62	  );
63	
64	const resultOf = (results, file) => results.find((result) => file.startsWith(`${result.root}/`));
65	
66	/** True when `path` (relative to a root or package) fits `layout`. */
67	function fits(layout, path) {
68	  const [first, ...rest] = path.split('/');
69	  return rest.length === 0 ? layout.files.includes(first) : layout.folders.includes(first);
70	}
71	
72	function isAllowed(result, file) {
73	  const path = file.slice(result.root.length + 1);
74	  const [first, ...rest] = path.split('/');
75	  if (!fits(LAYOUT.root, path)) {
76	    return false;
77	  }
78	  if (rest.length > 1 && CONFIG_FILE.test(rest.at(-1))) {
79	    return false;
80	  }
81	  return rest.length === 0 || fits(LAYOUT[first], rest.join('/'));
82	}
83	
84	function missingRoles({ contract, results, files }) {
85	  return results.flatMap((result) =>
86	    PACKAGE_KINDS.flatMap((kind) => {
87	      const held = new Set(
88	        files
89	          .filter((file) => file.startsWith(`${result[kind]}/`) && isRoleSource(file))
90	          .map(contract.roleOf),
91	      );
92	      return contract.requiredRoles[kind]
93	        .filter((role) => !held.has(role))
94	        .map((role) => ({ kind: 'missing-role', result: result.root, role }));
95	    }),
96	  );
97	}
98	
99	function unexpectedFiles({ results, files }) {
100	  return files.flatMap((file) => {
101	    const result = resultOf(results, file);
102	    return result && !isAllowed(result, file)
103	      ? [{ kind: 'unexpected-file', result: result.root, path: file }]
104	      : [];
105	  });
106	}
107	
108	function symlinks({ results, symlinks: paths }) {
109	  return paths.flatMap((path) => {
110	    const result = resultOf(results, path);
111	    return result ? [{ kind: 'symlink', result: result.root, path }] : [];
112	  });
113	}
114	
115	function dependencyProblems(manifest, reference, referenceDirectory) {
116	  const workspace = [];
117	  const problems = [];
118	  for (const field of DEPENDENCY_FIELDS) {
119	    for (const [name, range] of Object.entries(manifest[field] ?? {})) {
120	      if (range.startsWith('workspace:')) {
121	        workspace.push(name);
122	      } else if (reference[field]?.[name] !== range) {
123	        problems.push(
124	          `${field} "${name}": "${range}" is not in ${referenceDirectory}/package.json; use only its dependencies and ranges`,
125	        );
126	      }
127	    }
128	  }
129	  return { workspace: workspace.sort(), problems };
130	}
131	
132	/**
133	 * Every field other than the name and the dependencies matches the reference
134	 * package of the same kind, with the reference's scope read as this result's.
135	 */
136	function fieldProblems(manifest, reference, referenceDirectory, rename) {
137	  const fields = [...new Set([...Object.keys(reference), ...Object.keys(manifest)])].filter(
138	    (field) => field !== 'name' && !DEPENDENCY_FIELDS.includes(field),
139	  );
140	  return fields
141	    .map((field) => [field, canonical(manifest[field]), rename(canonical(reference[field]))])
142	    .filter(([, actual, expected]) => actual !== expected)
143	    .map(
144	      ([field, actual, expected]) =>
145	        `"${field}" is ${actual ?? 'missing'}; ${referenceDirectory}/package.json has ${expected ?? 'none'}`,
146	    );
147	}
148	
149	function manifestProblems(
150	  manifest,
151	  reference,
152	  { referenceDirectory, referenceScope, scope, kind },
153	) {
154	  const name = `@${scope}/${kind}`;
155	  const rename = (text) => text?.replaceAll(`@${referenceScope}/`, `@${scope}/`);
156	  const expectedWorkspace = kind === 'web' ? [`@${scope}/api`, '@repo/ui'].sort() : [];
157	  const { workspace, problems } = dependencyProblems(manifest, reference, referenceDirectory);
158	  return [
159	    manifest.name !== name && `name is "${manifest.name}"; name it "${name}"`,
160	    ...fieldProblems(manifest, reference, referenceDirectory, rename),
161	    ...problems,
162	    !sameList(workspace, expectedWorkspace) &&
163	      `workspace dependencies are [${workspace}]; list exactly [${expectedWorkspace}]`,
164	  ].filter(Boolean);
165	}
166	
167	function manifests({ results, manifests: byDirectory }) {
168	  const [reference] = results;
169	  return results.flatMap((result) =>
170	    PACKAGE_KINDS.flatMap((kind) => {
171	      const directory = result[kind];
172	      const manifest = byDirectory.get(directory);
173	      const problems = manifest
174	        ? manifestProblems(manifest, byDirectory.get(reference[kind]) ?? {}, {
175	            referenceDirectory: reference[kind],
176	            referenceScope: reference.scope,
177	            scope: result.scope,
178	            kind,
179	          })
180	        : ['is missing'];
181	      return problems.map((problem) => ({ kind: 'manifest', package: directory, problem }));
182	    }),
183	  );
184	}
185	
186	function incompleteResults({ results, files }) {
187	  const roots = new Set(
188	    files
189	      .filter((file) => file.startsWith('showcase/') && file.split('/').length > 2)
190	      .map((file) => file.split('/').slice(0, 2).join('/'))
191	      .filter((root) => !results.some((result) => result.root === root)),
192	  );
193	  return [...roots].flatMap((root) =>
194	    PACKAGE_KINDS.map((kind) => `${root}/${kind}/package.json`)
195	      .filter((manifest) => !files.includes(manifest))
196	      .map((missing) => ({ kind: 'incomplete-result', root, missing })),
197	  );
198	}
199	
200	const isE2eSpec = (result, file) =>
201	  file.startsWith(`${result.web}/e2e/`) && file.endsWith('.spec.ts');
202	
203	function missingE2e({ results, files }) {
204	  return results
205	    .filter((result) => !files.some((file) => isE2eSpec(result, file)))
206	    .map((result) => ({ kind: 'missing-e2e', package: result.web }));
207	}
208	
209	function crossResultImports({ results, edges }) {
210	  return edges
211	    .filter((edge) => {
212	      const from = resultOf(results, edge.from);
213	      const to = resultOf(results, edge.to);
214	      return from && to && from !== to;
215	    })
216	    .map(({ from, to }) => ({ kind: 'cross-result-import', from, to }));
217	}
218	
219	function suppressions({ results, files, readText }) {
220	  return files
221	    .filter((file) => resultOf(results, file))
222	    .flatMap((path) =>
223	      readText(path)
224	        .split('\n')
225	        .flatMap((text, index) =>
226	          SUPPRESSION.test(text) ? [{ kind: 'suppression', path, line: index + 1 }] : [],
227	        ),
228	    );
229	}
230	
231	const ROLE_TABLE = 'see .agents/project/ARCHITECTURE.md';
232	
233	const LAYOUT_TEXT = Object.values(LAYOUT)
234	  .map(
235	    ({ label, files, folders }) =>
236	      `${label} holds ${[...files, ...folders.map((folder) => `${folder}/`)].join(', ')}`,
237	  )
238	  .join('; ');
239	
240	/** One entry per rule: `find` gives its violations, `describe` one line naming the fix. */
241	const RULES = {
242	  'missing-role': {
243	    find: missingRoles,
244	    describe: (violation) =>
245	      `missing-role ${violation.result}: no file holds the ${violation.role} role; add it (${ROLE_TABLE}).`,
246	  },
247	  'unexpected-file': {
248	    find: unexpectedFiles,
249	    describe: (violation) =>
250	      `unexpected-file ${violation.path}: ${LAYOUT_TEXT}; a tool config lives only at the repository root. Move or delete it.`,
251	  },
252	  symlink: {
253	    find: symlinks,
254	    describe: (violation) =>
255	      `symlink ${violation.path}: a result holds regular files only, so every gate reads them; copy the file or import the package.`,
256	  },
257	  manifest: {
258	    find: manifests,
259	    describe: (violation) => `manifest ${violation.package}/package.json: ${violation.problem}.`,
260	  },
261	  'incomplete-result': {
262	    find: incompleteResults,
263	    describe: (violation) =>
264	      `incomplete-result ${violation.root}: ${violation.missing} is missing; a result is a web and an api package.`,
265	  },
266	  'missing-e2e': {
267	    find: missingE2e,
268	    describe: (violation) =>
269	      `missing-e2e ${violation.package}: add at least one e2e/**/*.spec.ts, the result's behaviour map.`,
270	  },
271	  'cross-result-import': {
272	    find: crossResultImports,
273	    describe: (violation) =>
274	      `cross-result-import ${violation.from} -> ${violation.to}: a result imports only its own packages and packages/ui.`,
275	  },
276	  suppression: {
277	    find: suppressions,
278	    describe: (violation) =>
279	      `suppression ${violation.path}:${violation.line}: a result holds no suppression directive; fix the finding instead.`,
280	  },
281	};
282	
283	/**
284	 * Every violation of the structure rules, in rule order. Pure.
285	 *
286	 * @param {{
287	 *   contract: import('./contract.mjs').Contract,
288	 *   results: readonly import('../results.d.mts').Result[],
289	 *   files: readonly string[],
290	 *   edges: readonly import('./graph.mjs').FileEdge[],
291	 *   symlinks: readonly string[],
292	 *   manifests: ReadonlyMap<string, Record<string, any>>,
293	 *   readText: (path: string) => string,
294	 * }} input
295	 */
296	export function validateStructure(input) {
297	  const sorted = { ...input, files: [...input.files].sort() };
298	  return Object.values(RULES).flatMap((rule) => rule.find(sorted));
299	}
300	
301	function main(root) {
302	  const repository = readRepository(root);
303	  const manifestPaths = repository.results
304	    .flatMap((result) => PACKAGE_KINDS.map((kind) => result[kind]))
305	    .filter((directory) => existsSync(join(root, directory, 'package.json')));
306	  const violations = validateStructure({
307	    ...repository,
308	    manifests: new Map(
309	      manifestPaths.map((directory) => [
310	        directory,
311	        JSON.parse(readFileSync(join(root, directory, 'package.json'), 'utf8')),
312	      ]),
313	    ),
314	    readText: (path) => readFileSync(join(root, path), 'utf8'),
315	  });
316	  if (violations.length > 0) {
317	    console.error(
318	      violations.map((violation) => RULES[violation.kind].describe(violation)).join('\n'),
319	    );
320	    return false;
321	  }
322	  const { results } = repository;
323	  const count = `${results.length} result${results.length === 1 ? '' : 's'}`;
324	  console.log(
325	    `OK: ${count} checked against the structure contract (${results.map((result) => result.id).join(', ')}).`,
326	  );
327	  return true;
328	}
329	
330	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
331	  runCli(main);
332	}
333

