728	    const isEffectResolver = (property) =>
729	      property.type === 'Property' &&
730	      !property.computed &&
731	      (property.key.name ?? property.key.value) === 'resolver' &&
732	      property.value.type === 'CallExpression' &&
733	      resolver.names(property.value.callee) &&
734	      property.value.arguments.length === 1 &&
735	      standardSchema.wraps(property.value.arguments[0]);
736	    return {
737	      ImportDeclaration(node) {
738	        useForm.ImportDeclaration(node);
739	        resolver.ImportDeclaration(node);
740	        standardSchema.ImportDeclaration(node);
741	      },
742	      CallExpression(node) {
743	        if (!useForm.names(node.callee)) {
744	          return;
745	        }
746	        const [options] = node.arguments;
747	        const valid =
748	          options?.type === 'ObjectExpression' &&
749	          options.properties.some(isEffectResolver) &&
750	          !options.properties.some((property) => property.type === 'SpreadElement');
751	        if (!valid) {
752	          context.report({ node, messageId: 'resolver' });
753	        }
754	      },
755	    };
756	  },
757	};
758	
759	export default {
760	  meta: { name: 'policy' },
761	  rules: {
762	    'one-component-per-file': oneComponentPerFile,
763	    'state-and-effects-in-hooks': stateAndEffectsInHooks,
764	    'handler-names': handlerNames,
765	    'callback-prop-names': callbackPropNames,
766	    'pages-in-routes': pagesInRoutes,
767	    'file-matches-export': fileMatchesExport,
768	    'folder-names': folderNames,
769	    'role-named-folders': roleNamedFolders,
770	    'test-beside-subject': testBesideSubject,
