import { existsSync } from 'node:fs';
import type { Config } from 'jest';

/**
 * Three projects: `web` (jsdom) for every web package and the ui kit, `api`
 * (node) for every api package, and `tooling` for the gate scripts. Each result
 * in `apps/` or `showcase/<id>/` joins by path, with no per-result entry. The
 * transform is @swc/jest (fast, no Babel). Coverage is gated so a feature cannot
 * ship under-tested — see `.agents/project/DEFINITION_OF_DONE.md`.
 */
const existingRoots = (...folders: string[]) =>
  folders.filter((folder) => existsSync(folder)).map((folder) => `<rootDir>/${folder}`);

const shared = {
  setupFilesAfterEnv: ['<rootDir>/jest.setup.ts'],
  moduleNameMapper: {
    '\\.(css|less|scss|sass)$': '<rootDir>/jest.style-stub.cjs',
  },
  transform: {
    // Effect 4 ships ES modules only and reads `import.meta?.env`, which has no
    // CommonJS form; under Jest there is no Vite env, so it reads as undefined.
    '/node_modules/(\\.pnpm/)?effect[@/].+\\.js$': [
      '@swc/jest',
      { jsc: { transform: { optimizer: { globals: { vars: { 'import.meta': 'undefined' } } } } } },
    ],
    // Also transform .mjs so scripts/*.mjs (e.g. validate-pr-body.mjs) can be
    // imported directly by their co-located tests.
    '^.+\\.(t|j)sx?$|^.+\\.mjs$': [
      '@swc/jest',
      {
        jsc: {
          parser: { syntax: 'typescript', tsx: true },
          transform: { react: { runtime: 'automatic' } },
        },
      },
    ],
  },
  transformIgnorePatterns: ['/node_modules/(?!(\\.pnpm/)?effect[@/])'],
} satisfies Config;

const config: Config = {
  // Clears the hook's and CI's variables before any worker starts (ADR 0042).
  globalSetup: '<rootDir>/scripts/jest-global-setup.mjs',
  projects: [
    {
      ...shared,
      displayName: 'web',
      testEnvironment: 'jsdom',
      roots: existingRoots('apps', 'showcase', 'packages'),
      testMatch: [
        '<rootDir>/{apps,showcase/*}/web/src/**/*.test.{ts,tsx}',
        '<rootDir>/packages/*/src/**/*.test.{ts,tsx}',
      ],
    },
    {
      ...shared,
      displayName: 'api',
      testEnvironment: 'node',
      roots: existingRoots('apps', 'showcase'),
      testMatch: ['<rootDir>/{apps,showcase/*}/api/src/**/*.test.{ts,tsx}'],
    },
    {
      ...shared,
      displayName: 'tooling',
      testEnvironment: 'jsdom',
      roots: existingRoots('scripts', 'tooling'),
      testMatch: ['<rootDir>/scripts/**/*.test.{ts,tsx}', '<rootDir>/tooling/**/*.test.{ts,tsx}'],
    },
  ],
  collectCoverageFrom: [
    '{apps,showcase/*}/*/src/**/*.{ts,tsx}',
    'packages/*/src/**/*.{ts,tsx}',
    '!**/*.d.ts',
    // Each project skips its own test files; this keeps one project from
    // counting another's tests as untested sources.
    '!**/*.test.{ts,tsx}',
    // Excluded by design: index.ts files are pure re-export barriers; main.tsx,
    // App.tsx and the api's server.ts are composition roots, exercised by the
    // E2E behaviour map (each result's e2e/ folder) rather than the unit suite.
    // Feature logic is NOT excluded. scripts/jest-scope.test.ts holds this list
    // to that set.
    '!{apps,showcase/*,packages}/**/src/**/index.ts',
    '!{apps,showcase/*}/web/src/main.tsx',
    '!{apps,showcase/*}/web/src/App.tsx',
    '!{apps,showcase/*}/api/src/server.ts',
  ],
  // Jest's defaults plus json-summary, which tooling/coverage-by-result.mjs
  // reads to hold each result to the same threshold on its own.
  coverageReporters: ['clover', 'json', 'lcov', 'text', 'json-summary'],
  coverageThreshold: {
    global: { branches: 80, functions: 80, lines: 80, statements: 80 },
  },
};

export default config;
import { defineConfig, devices, type PlaywrightTestConfig } from '@playwright/test';
import { listResults } from './tooling/results.mjs';

/**
 * Playwright is the browser harness for the behaviour map. Each result
 * (`apps/`, then every `showcase/<id>/`) gets one Chromium project that runs
 * every spec in `<result>/web/e2e/`, and two servers: its api on Node and its
 * web app on the Vite dev server, which proxies `/trpc` to that api. Each
 * showcase result also gets `<id>-acceptance`, which runs the fixed Todo
 * acceptance spec in `tooling/trial/acceptance/` against the same servers
 * (ADR 0034).
 *
 * `E2E_BASE_URL` points the reference project at a web server you manage
 * yourself, such as the built preview on :3000, which proxies `/trpc` to the
 * api on :3001 that Playwright still starts.
 */
const externalBaseUrl = process.env.E2E_BASE_URL;
const reuseExistingServer = !process.env.CI;
const results = listResults(import.meta.dirname);

type WebServer = Extract<PlaywrightTestConfig['webServer'], readonly unknown[]>[number];

const webUrl = (port: number) => `http://127.0.0.1:${port}`;
const usesExternalServer = (id: string) => id === 'reference' && Boolean(externalBaseUrl);

export default defineConfig({
  fullyParallel: true,
  forbidOnly: Boolean(process.env.CI),
  retries: process.env.CI ? 2 : 0,
  reporter: process.env.CI ? [['html', { open: 'never' }], ['github']] : 'list',
  use: { trace: 'on-first-retry' },
  projects: [
    ...results.map(({ id, web, ports }) => ({
      name: id,
      testDir: `./${web}/e2e`,
      use: {
        ...devices['Desktop Chrome'],
        baseURL: usesExternalServer(id) ? externalBaseUrl : webUrl(ports.web),
      },
    })),
    ...results
      .filter(({ id }) => id !== 'reference')
      .map(({ id, ports }) => ({
        name: `${id}-acceptance`,
        testDir: './tooling/trial/acceptance',
        use: { ...devices['Desktop Chrome'], baseURL: webUrl(ports.web) },
      })),
  ],
  webServer: results.flatMap(({ id, web, api, ports }): WebServer[] => [
    {
      command: `node ${api}/src/server.ts`,
      env: { PORT: String(ports.api) },
      port: ports.api,
      reuseExistingServer,
      timeout: 60_000,
    },
    ...(usesExternalServer(id)
      ? []
      : [
          {
            command: `pnpm exec vite --host 127.0.0.1 --port ${ports.web} --strictPort`,
            cwd: web,
            env: { API_ORIGIN: webUrl(ports.api) },
            url: webUrl(ports.web),
            reuseExistingServer,
            timeout: 120_000,
          },
        ]),
  ]),
});
#!/usr/bin/env node
/**
 * Holds every result to the coverage threshold on its own, so one result
 * cannot hide behind another's coverage in the global total (ADR 0034).
 * `pnpm test:coverage` runs it after Jest writes `coverage/coverage-summary.json`.
 * The global threshold in `jest.config.ts` still applies, and still covers
 * `packages/ui`, which belongs to no result.
 */

import { existsSync, readFileSync } from 'node:fs';
import { join, relative } from 'node:path';
import { pathToFileURL } from 'node:url';
import { listResults } from './results.mjs';

const THRESHOLD = 80;
const METRICS = ['lines', 'statements', 'functions', 'branches'];
const SUMMARY = 'coverage/coverage-summary.json';

/**
 * @typedef {{ total: number, covered: number }} Count
 * @typedef {Record<string, Record<string, Count>>} CoverageSummary  Jest's json-summary: absolute path (or "total") to metric counts
 */

/** Each metric's covered and total counts over the files of one result. */
function totals(files) {
  return Object.fromEntries(
    METRICS.map((name) => [
      name,
      files.reduce(
        (sum, counts) => ({
          covered: sum.covered + counts[name].covered,
          total: sum.total + counts[name].total,
        }),
        { covered: 0, total: 0 },
      ),
    ]),
  );
}

/** Istanbul's percentage, floored to two decimals, which Jest's global threshold compares. */
const percent = ({ covered, total }) =>
  total === 0 ? 100 : Math.floor((1000 * 100 * covered) / total / 10) / 100;

/**
 * One line per result and metric under the threshold, or per result with no
 * source in the summary.
 *
 * @param {CoverageSummary} summary
 * @param {readonly import('./results.d.mts').Result[]} results
 * @param {string} root
 */
export function coverageShortfalls(summary, results, root) {
  const entries = Object.entries(summary)
    .filter(([path]) => path !== 'total')
    .map(([path, counts]) => [relative(root, path), counts]);
  return results.flatMap(({ id, web, api }) => {
    const files = entries
      .filter(([path]) => path.startsWith(`${web}/`) || path.startsWith(`${api}/`))
      .map(([, counts]) => counts);
    if (files.length === 0) {
      return [`${id}: no source file in the coverage summary`];
    }
    const sums = totals(files);
    return METRICS.filter((name) => percent(sums[name]) < THRESHOLD).map(
      (name) => `${id}: ${name} ${percent(sums[name]).toFixed(2)}% < ${THRESHOLD}%`,
    );
  });
}

function main(root) {
  const path = join(root, SUMMARY);
  if (!existsSync(path)) {
    console.error(`${SUMMARY} is missing. Run Jest with coverage first (pnpm test:coverage).`);
    return 1;
  }
  const results = listResults(root);
  const shortfalls = coverageShortfalls(JSON.parse(readFileSync(path, 'utf8')), results, root);
  if (shortfalls.length > 0) {
    console.error(`Coverage per result is under ${THRESHOLD}%:\n${shortfalls.join('\n')}`);
    return 1;
  }
  console.log(
    `Coverage per result is at ${THRESHOLD}% or more: ${results.map(({ id }) => id).join(', ')}`,
  );
  return 0;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  process.exit(main(process.cwd()));
}

